/* Native modules in a logo-side dropdown; selected native submenu stays in the column.
   The logo and "All apps" lead back to the app menu (portal home), also in a
   new tab that has no history to swipe back to. */
(()=>{'use strict';if(window.__ufModuleHeader)return;window.__ufModuleHeader=true;
const style=document.createElement('style');style.textContent=`
body.uf-module-header .uf-hide-home,body.uf-module-header #desk-dock,body.uf-module-header .sidebar-header{display:none!important}
.uf-app-heading{display:flex;align-items:center;gap:8px;padding:12px;min-height:66px;flex:none}
.uf-app-heading img{width:40px;height:40px;object-fit:contain;border-radius:9px;flex-shrink:0}
.uf-module-picker{display:flex;align-items:center;justify-content:space-between;gap:8px;min-width:0;flex:1;border:0;background:transparent;color:var(--text-color);padding:8px 4px;font:inherit;font-weight:500;text-align:left;border-radius:6px;cursor:pointer}
.uf-module-picker span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.uf-module-picker svg{flex-shrink:0;width:16px;height:16px}.uf-module-picker:hover{background:var(--control-bg)}
.uf-fixed-actions{padding:0 8px;flex:none}.uf-fixed-actions button{display:flex;align-items:center;justify-content:flex-start;gap:8px;width:100%;height:28px;margin:0 0 2px;padding:0 8px;border:0;border-radius:var(--radius,6px);background:transparent;color:var(--ink-gray-6);text-align:left;font-family:inherit;font-size:var(--text-sm);font-weight:var(--font-weight-regular,400);line-height:1.15;letter-spacing:.02em;cursor:pointer}.uf-fixed-actions button:hover{background:var(--control-bg)}.uf-fixed-actions button>span,.uf-fixed-actions a>span{flex:1;min-width:0}.uf-fixed-actions a{display:flex;align-items:center;gap:8px;width:100%;height:28px;margin:0 0 2px;padding:0 8px;border-radius:var(--radius,6px);color:var(--ink-gray-6);font-size:var(--text-sm);text-decoration:none}.uf-fixed-actions a:hover{background:var(--control-bg);text-decoration:none}.uf-app-home{display:flex;flex-shrink:0;border-radius:9px}.uf-app-home:hover{opacity:.85}.uf-fixed-actions svg{width:16px;height:16px;flex-shrink:0}body.uf-module-header .body-sidebar .dropdown-navbar-user{display:block!important}
body.uf-module-header .body-sidebar-top{overflow-x:hidden!important;min-width:0;border-top:1px solid var(--border-color);padding-top:8px!important}
body.uf-module-header:not(.uf-erp-utilities) .standard-items-band{display:none!important}
body.uf-module-header.uf-erp-utilities .standard-items-band>.navbar-modal-search-mobile,body.uf-module-header.uf-erp-utilities .standard-items-band>.sidebar-notification{display:block!important}
body.uf-module-header.uf-erp-utilities .standard-items-band{padding-top:0!important;margin-bottom:8px!important}
body.uf-module-header:not(.uf-erp-utilities) .uf-help{display:none!important}
`;document.head.append(style);
let queued=false,entryHandled=false;
const icon=name=>frappe.utils.icon(name,'sm');
function update(){const sidebar=window.frappe?.app?.sidebar,side=document.querySelector('.body-sidebar'),all=window.frappe?.boot?.module_sidebars;if(!sidebar?.current_module||!side||!all||!sidebar.sidebar_header)return;
 const module=sidebar.current_module,app=sidebar.get_sidebar_app(),appName=app?.app_name||all[module]?.app,modules=Object.keys(all).filter(k=>all[k].app===appName);if(!modules.length)return;
 document.body.classList.add('uf-module-header');document.body.classList.toggle('uf-erp-utilities',appName==='erpnext');
 let heading=side.querySelector('.uf-app-heading');if(!heading){heading=document.createElement('div');heading.className='uf-app-heading';side.prepend(heading);const home=document.createElement('a');home.href='/';home.target='_top';home.className='uf-app-home';home.title='All apps';home.setAttribute('aria-label','All apps');const image=document.createElement('img');image.alt='';home.append(image);const button=document.createElement('button');button.type='button';button.className='uf-module-picker';button.setAttribute('aria-label','Choose module');button.innerHTML='<span></span>'+icon('chevron-down');heading.append(home,button);
  new frappe.ui.Dropdown({trigger:window.jQuery(button),options:()=>{const current=sidebar.get_sidebar_app();const name=current?.app_name||frappe.boot.module_sidebars[sidebar.current_module]?.app;return Object.entries(frappe.boot.module_sidebars).filter(([k,v])=>v.app===name).map(([key,v])=>({name:'module-'+key,label:v.label||key,icon:frappe.get_module_icon(key),onclick:()=>{sidebar.open_module(key);refresh();}}));}});
 }
 let logo=app?.app_logo_url;if(Array.isArray(logo))logo=logo[0];const image=heading.querySelector('img');if(logo&&image.getAttribute('src')!==logo)image.src=logo;image.hidden=!logo;heading.title=app?.app_title||appName;
 const label=all[module]?.label||module,span=heading.querySelector('button span');if(span.textContent!==label)span.textContent=label;
 let actions=side.querySelector('.uf-fixed-actions');if(!actions){actions=document.createElement('div');actions.className='uf-fixed-actions';heading.after(actions);const apps=document.createElement('a');apps.href='/';apps.target='_top';apps.className='uf-all-apps';apps.innerHTML=icon('grid')+'<span>All apps</span>';actions.append(apps);const edit=document.createElement('button');edit.type='button';edit.innerHTML=icon('pencil')+'<span>Edit Sidebar</span>';edit.onclick=()=>sidebar.sidebar_header.menu_items().flatMap(g=>g.options||[]).find(x=>x.name==='edit-sidebar')?.onclick?.();actions.append(edit);const help=document.createElement('button');help.type='button';help.className='uf-help';help.innerHTML=icon('info')+'<span>Help</span>'+icon('chevron-down');actions.append(help);new frappe.ui.Dropdown({trigger:window.jQuery(help),options:()=>sidebar.sidebar_header.get_help_siblings()});}
 for(const anchor of side.querySelectorAll('.sidebar-items a.item-anchor')){if(anchor.querySelector('.sidebar-item-label')?.textContent.trim()==='Home')(anchor.closest('.sidebar-item-container')||anchor.closest('.standard-sidebar-item')||anchor).classList.add('uf-hide-home');}
 if(!entryHandled){entryHandled=true;const u=new URL(location.href);if(u.searchParams.has('uf_entry')){u.searchParams.delete('uf_entry');history.replaceState(history.state,'',u.pathname+u.search+u.hash);if(module!==modules[0]){sidebar.open_module(modules[0]);refresh();}}}
}
function refresh(){if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;update();});}
new MutationObserver(refresh).observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:['data-title']});let wired=false;const startup=setInterval(()=>{refresh();if(!wired&&window.jQuery){wired=true;jQuery(document).on('page-change sidebar-expand',refresh);}},250);setTimeout(()=>clearInterval(startup),30000);addEventListener('focus',refresh);addEventListener('pageshow',refresh);addEventListener('online',refresh);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refresh();});refresh();})();
